INSERT INTO `dish_evaluation` VALUES (1,1,1001,1,'林晓',1,NULL,'宫保鸡丁',5,'味道正宗，分量足，配送也快，好评！',NULL,0,'感谢您的认可，欢迎下次光临！','2026-09-01 14:00:00',1,'2026-09-01 13:05:00','2026-09-01 14:00:00',1,1,0),(2,1,1001,1,'林晓',9,NULL,'扬州炒饭',4,'炒饭粒粒分明，配料挺足，口感不错。',NULL,0,NULL,NULL,1,'2026-09-01 13:06:00','2026-09-01 13:06:00',1,1,0),(3,1,1002,2,'黄志强',8,NULL,'口水鸡',5,'麻辣鲜香，鸡肉很嫩，红油特别香，就是稍微有点辣。',NULL,0,'感谢支持，辣度可以在下单时备注调整哦！','2026-09-01 21:00:00',1,'2026-09-01 20:30:00','2026-09-01 21:00:00',2,1,0),(4,1,1003,3,'苏婉婷',2,NULL,'红烧肉',5,'肥而不腻，入口即化，甜咸适中，配米饭绝了。',NULL,0,NULL,NULL,1,'2026-09-02 13:40:00','2026-09-02 13:40:00',3,1,0),(5,1,1004,4,'高建军',5,NULL,'鱼香肉丝',5,'酸甜可口，分量足，家里人都很喜欢。',NULL,0,NULL,NULL,0,'2026-09-03 21:00:00','2026-09-03 21:00:00',4,1,0),(6,1,1005,5,'钱多多',4,NULL,'糖醋里脊',4,'炸得酥脆，酱汁酸甜刚好，就是可以再少放点糖。',NULL,0,NULL,NULL,1,'2026-09-05 13:10:00','2026-09-05 13:10:00',5,1,0),(7,1,1005,5,'钱多多',23,NULL,'柠檬水',3,'柠檬水清爽解腻，不过甜度有点高，希望出无糖版。',NULL,0,NULL,NULL,1,'2026-09-05 13:11:00','2026-09-05 13:11:00',5,1,0),(8,1,1006,6,'周子涵',6,NULL,'辣子鸡',4,'香辣够味，不过辣椒放太多、鸡肉偏少了点。',NULL,1,NULL,NULL,1,'2026-09-07 20:15:00','2026-09-07 20:15:00',6,1,0),(9,1,1006,6,'周子涵',8,NULL,'口水鸡',5,'回购好多次了，口味一直很稳定。',NULL,0,NULL,NULL,1,'2026-09-07 20:16:00','2026-09-07 20:16:00',6,1,0),(10,1,1007,7,'吴彩霞',11,NULL,'牛肉面',5,'汤头浓郁，牛肉给得实在，面条也很劲道。',NULL,0,NULL,NULL,1,'2026-09-10 13:30:00','2026-09-10 13:30:00',7,1,0),(11,1,1008,8,'郑国豪',3,NULL,'麻婆豆腐',5,'麻辣下饭，豆腐嫩滑，赞！',NULL,0,'谢谢好评，麻婆豆腐是我们的招牌新菜品！','2026-09-12 22:00:00',1,'2026-09-12 21:20:00','2026-09-12 22:00:00',8,1,0),(12,1,1009,9,'王美琳',12,NULL,'小笼包',5,'皮薄汁多，趁热吃超满足。',NULL,0,NULL,NULL,1,'2026-09-15 13:25:00','2026-09-15 13:25:00',9,1,0),(13,1,1010,10,'冯磊',1,NULL,'宫保鸡丁',4,'整体不错，就是口味稍微偏甜了一点。',NULL,0,NULL,NULL,1,'2026-09-18 20:05:00','2026-09-18 20:05:00',10,1,0),(14,1,2001,1,'林晓',3,NULL,'麻婆豆腐',5,'很正宗，麻辣味足，超下饭。',NULL,0,NULL,NULL,1,'2026-09-20 13:45:00','2026-09-20 13:45:00',1,1,0),(15,1,2001,1,'林晓',26,NULL,'烤羊肉串',5,'香嫩可口，孜然味浓，夜宵必备。',NULL,0,'感谢喜欢，烤串都是现烤现送的！','2026-09-20 22:30:00',0,'2026-09-20 22:10:00','2026-09-20 22:30:00',1,1,0),(16,1,2002,2,'黄志强',6,NULL,'辣子鸡',4,'味道可以，微辣刚好合我口味。',NULL,0,NULL,NULL,1,'2026-09-20 20:40:00','2026-09-20 20:40:00',2,1,0),(17,1,2002,2,'黄志强',17,NULL,'鸡米花',4,'外酥里嫩，当小食配餐不错。',NULL,1,NULL,NULL,1,'2026-09-20 20:41:00','2026-09-20 20:41:00',2,1,0),(18,1,2003,3,'苏婉婷',13,NULL,'夫妻肺片',5,'红油香，牛肉牛肚都入味，凉菜首选。',NULL,0,NULL,NULL,1,'2026-09-21 14:00:00','2026-09-21 14:00:00',3,1,0),(19,1,3001,4,'高建军',4,NULL,'糖醋里脊',5,'酸甜酥脆，孩子特别爱吃。',NULL,0,NULL,NULL,0,'2026-09-24 13:20:00','2026-09-24 13:20:00',4,1,0),(20,1,3002,5,'钱多多',3,NULL,'麻婆豆腐',5,'豆腐很嫩，辣度适中，好吃。',NULL,0,NULL,NULL,1,'2026-09-24 19:30:00','2026-09-24 19:30:00',5,1,0),(21,1,3003,6,'周子涵',4,NULL,'糖醋里脊',4,'外酥里嫩，酱汁不腻，整体满意。',NULL,0,NULL,NULL,1,'2026-09-25 12:15:00','2026-09-25 12:15:00',6,1,0),(22,1,3004,7,'吴彩霞',8,NULL,'口水鸡',5,'一如既往的好吃，配送也很快。',NULL,0,'感谢回购，我们会继续保持品质！','2026-09-25 13:20:00',1,'2026-09-25 12:50:00','2026-09-25 13:20:00',7,1,0),(23,1,3005,8,'郑国豪',2,NULL,'红烧肉',5,'软糯不柴，很下饭。',NULL,0,NULL,NULL,1,'2026-09-25 13:10:00','2026-09-25 13:10:00',8,1,0),(24,1,3006,9,'王美琳',5,NULL,'鱼香肉丝',5,'酸甜辣平衡得刚好，配饭一流。',NULL,0,NULL,NULL,1,'2026-09-23 21:40:00','2026-09-23 21:40:00',9,1,0);
