  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_record_order` (`order_id`),
  KEY `idx_record_tenant` (`tenant_id`),
  KEY `idx_record_user` (`tenant_id`,`user_id`)
